/*
 * 예비심사, 신규상장시 회사, 종목찾기 조회코드
 * 화면명 : ULDSTF0511, ULDSTF0512
 */
SEARCH_TYP_SEC = 'SEC'; //유가예비심사신규등록
SEARCH_TYP_SER = 'SER'; //유가예비심사등록조회
SEARCH_TYP_SLC = 'SLC'; //유가신규상장신규등록
SEARCH_TYP_SLR = 'SLR'; //유가신규상장등록조회
SEARCH_TYP_APF = 'APF'; //발행기관(예비심사포함)

SEARCH_TYP_KLC = 'KLC'; //코스닥신규상장신규등록
SEARCH_TYP_KLR = 'KLR'; //코스닥신규상장등록조회

LIST_CLSS_CD_10 = "10"; // 신규상장
LIST_CLSS_CD_20 = "20"; // 재상장
LIST_CLSS_CD_21 = "21"; // 재상장-분할
LIST_CLSS_CD_22 = "22"; // 재상장-합병
LIST_CLSS_CD_23 = "23"; // 재상장-폐지



/**
 * 신규상장시 조회구분 INDEX
 * NewListingUtil.java소스의  index하고 일치시킨다.
 */
