DIV_L_LISTING_BC = '2';
DIV_R_LISTING_EXEM_ST = '3';
DIV_R_LISTING_KSQ_EXEM_ST = '4';
DIV_R_LISTING_ST = '5';
DIV_R_LISTING_ISU = '6';
DIV_R_LISTING_KSQ_EXEM_ETF = '7';
DIV_R_LISTING_EXEM_ETF = '8';
DIV_R_LISTING_ETF_ISU = '9';
DIV_R_LISTING_EXEM_BC = '10';
DIV_R_LISTING_BC = '11';
DIV_R_LISTING_LP_MBR_NO = '12';
DIV_R_LISTING_DIST_PAY = '13';
DIV_R_CHK_DOUBLE_INPUT = '14';
DIV_R_CHK_SYMBL = '15';
DIV_R_GET_LIST_NO = '16';
DIV_R_LISTING_CORP_DSCL = '17';
DIV_R_LISTING_ST_ISU_DTL = '18';
DIV_R_LISTING_ETF_CREDTI = '19';
DIV_R_LISTING_BF_ISU = '20';
DIV_R_LISTING_ETF_CLSBZ = '21';
DIV_L_LISTING_ETF_DETAIL = '22';
DIV_L_LISTING_ETF_SEND = '23';
/**
 * @method
 * @name fn_getDsclsTitle
 * @description desc
 * @param {string} vComNm desc
 * @param {string} vListDD desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getDsclsTitle = function(vComNm, vListDD) {
    return "" + vComNm + ", 상장일 " + vListDD.substring(0, 4) + "." + vListDD.substring(4, 6) + "." + vListDD.substring(6, 8) + "";
};


/**
 * 예비심사와 신규상장의 목록검색시작일과 종료일자의 초기값 설정
 */
/**
 * @method
 * @name fn_initSearchDate
 * @description desc
 * @param {string} edtSDate desc
 * @param {string} edtEDate desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_initSearchDate = function(edtSDate, edtEDate) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edtSDate.text = cGetMinusDate2(vCurDate, 365*5);
    edtSDate.setValue('19000101');
    edtEDate.setValue($c.ut.cGetPlusDate2(vCurDate, 60));
};


/**
 * 신규상장시 상장종목팝업창
 */
/**
 * @method
 * @name fn_OpenDetailCorpIsu
 * @description desc
 * @param {string} row desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDetailCorpIsu = async function(row) {
    var secugrpId = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    if (row > 0) {
        //그리드에서 선택시
        fn_setBzProcsNo(row);
    } else {
        //신규버튼 선택시
        clickBzProcsNo = ""; //초기화

    }
    //alert("[fn_OpenDetail secugrpId]"+secugrpId);
    await $c.frame.CreateDialogFrame("DLG_NEWISUREG", "/listingcommon/ULDSTF92001.gfm", $c.lce.fn_getSecuGrpNm(secugrpId) + " 신규상장종목등록", 10, 10, 900, 650 + 40, "window");
};


/**
 * 신규상장시 상장종목팝업창
 * 2010.09.06 보호예수유가전용추가함
 *
 */
/**
 * @method
 * @name fn_OpenDetailCorpIsu_protect
 * @description desc
 * @param {string} row desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDetailCorpIsu_protect = async function(row) {
    var secugrpId = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    if (row > 0) {
        //그리드에서 선택시
        fn_setBzProcsNo(row);
    } else {
        //신규버튼 선택시
        clickBzProcsNo = ""; //초기화

    }
    //alert("[fn_OpenDetail secugrpId]"+secugrpId);
    await $c.frame.CreateDialogFrame("DLG_NEWISUREG", "/listingcommon/ULDSTF92026.gfm", $c.lce.fn_getSecuGrpNm(secugrpId) + " 신규상장종목등록", 10, 10, 920, 820, "window");
};


/**
 * 업무처리번호가 없는경우 종목마스터에서 정보를 가져온다.
 * 현재 코스닥정보를 가져오는데 사용
 */
/**
 * @method
 * @name fn_getCorpInfo_read_sync
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vIsurcd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getCorpInfo_read_sync = function(dtsObj, vIsurcd) {
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + scwin.DIV_R_LISTING_KSQ_EXEM_ST;
    url += "&ISUR_CD=" + vIsurcd;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};


/**
 * 유가예비심사정보를 가져오는데 사용
 */
/**
 * @method
 * @name fn_getExem_read_sync
