/**
 * 신규상장시 중복입력여부를 체크
 */
/**
 * @method
 * @name fn_checkDoubleInput
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkDoubleInput = function(dtsObj, vKey) {
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + scwin.DIV_R_CHK_DOUBLE_INPUT;
    url += "&P_KEY=" + vKey;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    var str = dtsObj.getCellData(1, "DBINPUT_YN");
    if (str == 'Y') {
        alert("[해당종목은 이미 신규상장처리중이라 신규입력할 수 없습니다.]");
        return true;
    } else if (str == 'N') {
        return false;
    }
};




/**
 * 상장번호를 생성
 */
/**
 * @method
 * @name fn_createListNo
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} dtsObjTgt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_createListNo = function(dtsObj, dtsObjTgt) {
    var str = $c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD);
    if (str == "") {
        alert("[시장구분]을 선택하세요.");
        return;
    } else {
        var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
        url += "&DIV_IDX=" + scwin.DIV_R_GET_LIST_NO;
        url += "&SPOT_ISU_TRD_MKT_TP_CD=" + str;
        dtsObj.DataID = encodeURI(url);
        dtsObj.Reset();
        dtsObjTgt.setCellData(1, "LIST_NO", dtsObj.getCellData(1, "LIST_NO"));
    }
};
/**
 * @method
 * @name fn_checkAcntclsMM
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkAcntclsMM = function(obj) {
    if ($c.stf.getObjectValue(obj).length == 1) {
        alert("[결산월]을 올바르게 입력하세요. 1월 -> 01월");
        obj.focus();
        return false;
    } else if ($c.stf.getObjectValue(obj).length == 2) {
        if (parseInt($c.stf.getObjectValue(obj), 10) > 12) {
            alert("[결산월]이 12월을 초과하였습니다. 다시입력하세요");
            obj.focus();
            return false;
        }
    } else if ($c.stf.getObjectValue(obj).length == 4) {
        if (parseInt($c.stf.getObjectValue(obj).substring(0, 2), 10) > 12) {
            alert("[결산월]이 12월을 초과하였습니다. 다시입력하세요");
            obj.focus();
            return false;
        }
    }
    return true;
};
/**
 * @method
 * @name fn_checkAcntclsMMDD
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkAcntclsMMDD = function(obj) {
    if ($c.stf.getObjectValue(obj).length != 4) {
        alert("[결산월일]을 올바르게 입력하세요. 1월1일 -> 01월01일");
        obj.focus();
        return false;
    }
    if (parseInt($c.stf.getObjectValue(obj).substring(0, 2), 10) > 12) {
        alert("[입력월]이 12월을 초과하였습니다. 다시입력하세요");
        obj.focus();
        return false;
    }
    if (parseInt($c.stf.getObjectValue(obj).substring(2, 4), 10) > 31) {
        alert("[입력일]이 31일을 초과하였습니다. 다시입력하세요");
        obj.focus();
        return false;
    }
    return true;
};
/**
 * @method
 * @name fn_checkDistPay
 * @description desc
 * @param {string} dts_obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkDistPay = function(dts_obj) {
    var isResult = false;
    for (i = 1; i <= dts_obj.getTotalRow(); i++) {
        var mmdd = dts_obj.getCellData(i, "EARNG_DISTR_BAS_MM") + dts_obj.getCellData(i, "EARNG_DISTR_BAS_DD");
        if (mmdd != "" && mmdd.length != 4) {
            alert("입력한 분배기준일 항목중 [(월,일)]을 정확히 입력해주세요. \n\n예 : 5월1일 -> 0501 ");
            return false;
            break;
        }
        isResult = true;
    }
    return isResult;
};



/**
 * 데이타셋에 값이 있는지 체크
 */
/**
 * @method
 * @name fn_CheckGridDataset
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckGridDataset = function(dtsObj, str) {
    var isNull = false;
    for (i = 1; i < dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, str) != "") {
            isNull = false;
            break;
        }
        isNull = true;
    }
    return isNull;
};
/**
 * @method
 * @name fn_grdDistPayExitEvent
 * @description desc
 * @param {string} row desc
 * @param {string} colid desc
 * @param {string} olddata desc
 * @param {string} dts_obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_grdDistPayExitEvent = function(row, colid, olddata, dts_obj) {
    if (colid == "EARNG_DISTR_BAS_MM" && eval(dts_obj.getCellData(row, "EARNG_DISTR_BAS_MM")) > 12) {
        alert("입력월을 확인하세요.");
        dts_obj.setCellData(row, "EARNG_DISTR_BAS_MM", "");
    } else if (colid == "EARNG_DISTR_BAS_DD" && eval(dts_obj.getCellData(row, "EARNG_DISTR_BAS_DD")) > 31) {
        alert("입력일을 확인하세요.");
        dts_obj.setCellData(row, "EARNG_DISTR_BAS_DD", "");
    }
};




/**
 * 분배기준일자를 가져오는 데이타 셋
 */
/**
 * @method
 * @name fn_read_sync_distr_pay
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vBzProcsNo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_read_sync_distr_pay = function(dtsObj, vBzProcsNo) {
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + scwin.DIV_R_LISTING_DIST_PAY;
    url += "&BZ_PROCS_NO=" + vBzProcsNo;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};


/**
 * 신규상장시 분배기준일정보를 입력하기 위해 데이타 셋을 갯수만큼 초기화함
 */
/**
 * @method
 * @name fn_initDistrPayGridData
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} initYn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_initDistrPayGridData = function(dtsObj, initYn) {
    if (initYn == "N") {
        var vdtsDistrPayrowCnt = dtsObj.getTotalRow();
        for (i = vdtsDistrPayrowCnt; i < 12; i++) {
            dtsObj.AddRow();
        }
    } else if (initYn == "Y") {
        for (j = 0; j < 12; j++) {
            dtsObj.AddRow();
        }
    }
    dtsObj.setFocusedCell(1, 0);
};



/**
 * 신규상장시 LP정보를 입력하기 위해 데이타 셋을 갯수만큼 초기화함
 */
/**
 * @method
 * @name fn_initLPGridData
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} initYn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_initLPGridData = function(dtsObj, initYn) {
    if (initYn == "N") {
        var vdtsDistrPayrowCnt = dtsObj.getTotalRow();
        for (i = vdtsDistrPayrowCnt; i < 15; i++) {
            dtsObj.AddRow();
        }
    } else if (initYn == "Y") {
        for (j = 0; j < 15; j++) {
            dtsObj.AddRow();
        }
    }
    dtsObj.setFocusedCell(1, 0);
};


/**
 * 신규상장시 LP정보를 입력한 갯수만큼 데이타 셋에 저장
 */
/**
 * @method
 * @name fn_setLPGridData
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setLPGridData = function(dtsObj, vKey) {
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        var vLpMbrNo = dtsObj.getCellData(i, "LP_MBR_NO");
        if (vLpMbrNo != " " && vLpMbrNo != "") {
            //alert('[vLpMbrNo>>>>>>>]'+vLpMbrNo);
            dtsObj.setCellData(i, "BZ_PROCS_NO", vKey);
            dtsObj.setCellData(i, "LP_CONTRT_DD", ''); //not null -> null
            dtsObj.setCellData(i, "LP_STRT_DD", ''); //not null -> null

        } else {
            dtsObj.DeleteRow(i);
            i--; // 삭제한 경우는 해당하는 위치에서 한번더 검색하게 함.

        }
    }
};





/**
 * 신규상장시 분배기준일정보를 입력한 갯수만큼 데이타 셋에 저장
 */
/**
 * @method
 * @name fn_setDistrPayGridData
 * @description desc
 * @param {string} dtsObjSave desc
 * @param {string} dtsObj desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setDistrPayGridData = function(dtsObjSave, dtsObj, vKey) {
    dtsObjSave.ClearData();
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        var vStdMM = dtsObj.getCellData(i, "EARNG_DISTR_BAS_MM");
        if (vStdMM != "") {
            dtsObjSave.AddRow();
            dtsObjSave.setCellData(i, "BZ_PROCS_NO", vKey);
            dtsObjSave.setCellData(i, "FISCYY_DISTR_BASDD_TP_CD", '2');
            dtsObjSave.setCellData(i, "EARNG_DISTR_BAS_MM", dtsObj.getCellData(i, "EARNG_DISTR_BAS_MM"));
            dtsObjSave.setCellData(i, "EARNG_DISTR_BAS_DD", dtsObj.getCellData(i, "EARNG_DISTR_BAS_DD"));
        }
    }
};





/**
 * 신규상장시 신용평가 정보를 입력한 갯수만큼 데이타 셋에 저장
 */
/**
 * @method
 * @name fn_setCreDitGridData
 * @description desc
 * @param {string} dtsObjSave desc
 * @param {string} dtsObj1 desc
 * @param {string} dtsObj2 desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setCreDitGridData = function(dtsObjSave, dtsObj1, dtsObj2, vKey) {
    dtsObjSave.ClearData();
    for (var i = 1; i <= dtsObj1.getTotalRow(); i++) {
        dtsObjSave.AddRow();
        dtsObjSave.setCellData(i, "BZ_PROCS_NO", vKey);
        dtsObjSave.setCellData(i, "CREDIT_GRD_CONTN", dtsObj1.getCellData(i, "CREDIT_GRD_CONTN"));
        dtsObjSave.setCellData(i, "CREDIT_VALU_INST_TP_CD", dtsObj1.getCellData(i, "CREDIT_VALU_INST_TP_CD"));
    }
    for (var i = 1; i <= dtsObj2.getTotalRow(); i++) {
        var k = eval(parseInt(i)) + 3;
        dtsObjSave.AddRow();
        dtsObjSave.setCellData(k, "BZ_PROCS_NO", vKey);
        dtsObjSave.setCellData(k, "CREDIT_GRD_CONTN", dtsObj2.getCellData(i, "CREDIT_GRD_CONTN"));
        dtsObjSave.setCellData(k, "CREDIT_VALU_INST_TP_CD", dtsObj2.getCellData(i, "CREDIT_VALU_INST_TP_CD"));
    }
};
